package com.lyra.studio; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; import android.app.Activity; import android.view.WindowManager; @DesignerComponent(version = 1, description = "Extensao para ajustar o comportamento da tela e do WebView quando o teclado virtual é aberto.", category = ComponentCategory.EXTENSION, nonVisible = true, iconName = "images/extension.png") @SimpleObject(external = true) public class KeyboardAdjustWebView extends AndroidNonvisibleComponent { private Activity activity; public KeyboardAdjustWebView(ComponentContainer container) { super(container.$form()); this.activity = container.$context(); } @SimpleFunction(description = "Habilita o redimensionamento da janela para que o conteúdo do WebView não seja coberto pelo teclado virtual.") public void EnableKeyboardResize() { /* Define o modo da janela para redimensionar o layout quando o teclado abrir */ activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); } }); } @SimpleFunction(description = "Restaura o comportamento padrão da tela em relação ao teclado virtual.") public void DisableKeyboardResize() { /* Restaura o modo padrão onde a tela não se redimensiona obrigatoriamente */ activity.runOnUiThread(new Runnable() { @Override public void run() { activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_PAN); } }); } }